module.exports = [
{ e: "🦖", art: { b: "🦖", s: ["🦴", "🌿", "🌋", "🏛️"], c: ["#2E4A1E", "#6A9A3A"] },
pt: { h: "O vovô trouxe uma caixa de papelão enorme e escreveu na frente: MUSEU DOS DINOSSAUROS. “Ele está vazio”, disse. “Por 30 noites, vamos descobrir um dinossauro ou um segredo deles e criar uma ficha para o museu.” Leo rugiu tão alto que o Pipoca se escondeu debaixo do sofá.", t: "O que eram os dinossauros?", f: "Os dinossauros foram répteis que dominaram a Terra por mais de 160 milhões de anos, entre cerca de 230 e 66 milhões de anos atrás. Havia dinossauros gigantes e pequenos, comedores de plantas e caçadores. Eles andavam com as pernas bem embaixo do corpo, e não abertas para os lados como os lagartos.", x: "A palavra dinossauro foi criada em 1842 pelo cientista inglês Richard Owen e quer dizer “lagarto terrível”. Mas os dinossauros nem eram lagartos!", s: ["Nenhum ser humano jamais viu um dinossauro gigante vivo: eles desapareceram milhões de anos antes de existirem pessoas.", "Já foram descritas mais de mil espécies de dinossauros, e novas são descobertas todo ano.", "Tudo o que sabemos sobre eles vem de fósseis: ossos, dentes, ovos, pegadas e até cocô petrificado!"], ex: { t: "Ossos de massinha", m: "massinha, palitos de dente, um prato", p: ["Faça vários “ossos” de massinha de tamanhos diferentes: um crânio, costelas, patas e uma cauda.", "Misture tudo no prato, como um fóssil espalhado na terra.", "Peça para alguém montar o esqueleto sem ver o desenho original. É assim que os paleontólogos trabalham: juntando pistas como um quebra-cabeça!"] }, at: "A entrada do museu", m: "uma caixa grande, cartolina, lápis de cor", p: ["Decore a caixa como um museu, com colunas e uma placa com o nome.", "Faça um ingresso com o seu nome como “Diretor do Museu”.", "Desenhe a primeira ficha: um dinossauro qualquer que você adore, com o nome e o tamanho dele."], q: "Qual é o seu dinossauro favorito? Por quê?" },
en: { h: "Grandpa brought in a huge cardboard box and wrote on the front: DINOSAUR MUSEUM. “It's empty,” he said. “For 30 nights, we'll discover a dinosaur or one of their secrets and make a card for the museum.” Leo roared so loudly that Popcorn hid under the couch.", t: "What were dinosaurs?", f: "Dinosaurs were reptiles that ruled the Earth for more than 160 million years, from about 230 to 66 million years ago. There were giant ones and small ones, plant-eaters and hunters. They walked with their legs straight under their bodies, not sprawled out to the sides like lizards.", x: "The word dinosaur was coined in 1842 by English scientist Richard Owen and means “terrible lizard.” But dinosaurs weren't even lizards!", s: ["No human has ever seen a giant dinosaur alive: they disappeared millions of years before there were people.", "More than a thousand dinosaur species have been described, and new ones are discovered every year.", "Everything we know about them comes from fossils: bones, teeth, eggs, footprints and even fossilized poop!"], ex: { t: "Play dough bones", m: "play dough, toothpicks, a plate", p: ["Make several play dough “bones” of different sizes: a skull, ribs, legs and a tail.", "Mix them all up on the plate, like a fossil scattered in the ground.", "Ask someone to put the skeleton together without seeing the original. That's how paleontologists work: fitting clues together like a puzzle!"] }, at: "The museum entrance", m: "a large box, poster board, colored pencils", p: ["Decorate the box like a museum, with columns and a name sign.", "Make a ticket with your name as “Museum Director.”", "Draw the first exhibit card: any dinosaur you love, with its name and size."], q: "What's your favorite dinosaur? Why?" },
es: { h: "El abuelo trajo una caja de cartón enorme y escribió en el frente: MUSEO DE LOS DINOSAURIOS. “Está vacío”, dijo. “Durante 30 noches vamos a descubrir un dinosaurio o uno de sus secretos y crear una ficha para el museo.” Leo rugió tan fuerte que Palomita se escondió debajo del sillón.", t: "¿Qué eran los dinosaurios?", f: "Los dinosaurios fueron reptiles que dominaron la Tierra durante más de 160 millones de años, entre hace unos 230 y 66 millones de años. Había dinosaurios gigantes y pequeños, comedores de plantas y cazadores. Caminaban con las patas bien debajo del cuerpo, y no abiertas hacia los costados como los lagartos.", x: "¡La palabra dinosaurio la creó en 1842 el científico inglés Richard Owen y quiere decir “lagarto terrible”. Pero los dinosaurios ni siquiera eran lagartos!", s: ["Ningún ser humano vio jamás un dinosaurio gigante vivo: desaparecieron millones de años antes de que existieran personas.", "Ya se describieron más de mil especies de dinosaurios, y cada año se descubren nuevas.", "Todo lo que sabemos de ellos viene de fósiles: huesos, dientes, huevos, huellas ¡y hasta caca petrificada!"], ex: { t: "Huesos de plastilina", m: "plastilina, palillos, un plato", p: ["Haz varios “huesos” de plastilina de distintos tamaños: un cráneo, costillas, patas y una cola.", "Mézclalos todos en el plato, como un fósil desparramado en la tierra.", "Pide a alguien que arme el esqueleto sin ver el dibujo original. ¡Así trabajan los paleontólogos: juntando pistas como un rompecabezas!"] }, at: "La entrada del museo", m: "una caja grande, cartulina, lápices de colores", p: ["Decora la caja como un museo, con columnas y un cartel con el nombre.", "Haz una entrada con tu nombre como “Director del Museo”.", "Dibuja la primera ficha: cualquier dinosaurio que te encante, con su nombre y su tamaño."], q: "¿Cuál es tu dinosaurio favorito? ¿Por qué?" } },

{ e: "⏳", art: { b: "⏳", s: ["🦕", "🌋", "🌿", "🕰️"], c: ["#3A2A0B", "#8A6A2C"] },
pt: { h: "Leo perguntou se os dinossauros viveram todos ao mesmo tempo, numa grande festa. O vovô riu e pegou um prato de papel. “Vamos transformar a história da Terra num relógio”, disse. “Vocês vão ver que os dinossauros chegaram quase no fim… e nós, no último segundo!”", t: "Uma viagem pelo tempo profundo", f: "Os dinossauros viveram numa época chamada Era Mesozoica, dividida em três períodos: Triássico, Jurássico e Cretáceo. Cada período durou dezenas de milhões de anos. Por isso, muitos dinossauros famosos nunca se encontraram: viveram em épocas muito distantes.", x: "Se toda a história da Terra coubesse em 12 horas de um relógio, os dinossauros apareceriam lá pelas 11h23 e desapareceriam por volta das 11h49. E os humanos? Só nos últimos 3 segundos antes do meio-dia!", s: ["O Triássico começou há uns 252 milhões de anos, e foi quando surgiram os primeiros dinossauros.", "O Jurássico foi a época dos grandes pescoçudos, como o Braquiossauro.", "No Cretáceo, o último período, viveram o Tiranossauro e o Tricerátops."], ex: { t: "Relógio da Terra", m: "um prato de papel, uma caneta, uma régua", p: ["Desenhe um relógio no prato, com os números de 1 a 12.", "Marque o começo da Terra no 12 do alto. Pinte um pedacinho entre 11h23 e 11h49: é a época dos dinossauros.", "Agora marque os humanos: um risquinho fino, colado no 12! Como somos novos no planeta!"] }, at: "Ficha das três épocas", m: "papel, lápis de cor", p: ["Divida uma ficha em três partes: Triássico, Jurássico e Cretáceo.", "Desenhe em cada parte uma paisagem e um dinossauro daquela época.", "Coloque a ficha no museu."], q: "Se você pudesse visitar um dos três períodos, qual escolheria?" },
en: { h: "Leo asked whether all the dinosaurs lived at the same time, like one big party. Grandpa laughed and picked up a paper plate. “Let's turn Earth's history into a clock,” he said. “You'll see that dinosaurs showed up near the end… and we arrived in the very last second!”", t: "A trip through deep time", f: "Dinosaurs lived in a time called the Mesozoic Era, divided into three periods: the Triassic, Jurassic and Cretaceous. Each period lasted tens of millions of years. That's why many famous dinosaurs never met: they lived very far apart in time.", x: "If all of Earth's history fit into 12 hours on a clock, dinosaurs would show up around 11:23 and disappear around 11:49. And humans? Only in the last 3 seconds before noon!", s: ["The Triassic began about 252 million years ago, and that's when the first dinosaurs appeared.", "The Jurassic was the age of the great long-necks, like Brachiosaurus.", "In the Cretaceous, the last period, lived Tyrannosaurus and Triceratops."], ex: { t: "Earth clock", m: "a paper plate, a pen, a ruler", p: ["Draw a clock on the plate with the numbers 1 to 12.", "Mark the start of Earth at the 12 on top. Color a small slice between 11:23 and 11:49: that's the dinosaur age.", "Now mark humans: a thin line right up against the 12! How new we are on the planet!"] }, at: "Three-ages card", m: "paper, colored pencils", p: ["Divide an exhibit card into three parts: Triassic, Jurassic and Cretaceous.", "In each part, draw a landscape and a dinosaur from that time.", "Put the card in the museum."], q: "If you could visit one of the three periods, which would you choose?" },
es: { h: "Leo preguntó si todos los dinosaurios vivieron al mismo tiempo, como en una gran fiesta. El abuelo se rió y tomó un plato de papel. “Vamos a convertir la historia de la Tierra en un reloj”, dijo. “¡Van a ver que los dinosaurios llegaron casi al final… y nosotros, en el último segundo!”", t: "Un viaje por el tiempo profundo", f: "Los dinosaurios vivieron en una época llamada Era Mesozoica, dividida en tres períodos: Triásico, Jurásico y Cretácico. Cada período duró decenas de millones de años. Por eso, muchos dinosaurios famosos nunca se encontraron: vivieron en épocas muy lejanas.", x: "¡Si toda la historia de la Tierra cupiera en 12 horas de un reloj, los dinosaurios aparecerían alrededor de las 11:23 y desaparecerían cerca de las 11:49. ¿Y los humanos? Solo en los últimos 3 segundos antes del mediodía!", s: ["El Triásico empezó hace unos 252 millones de años, y ahí aparecieron los primeros dinosaurios.", "El Jurásico fue la época de los grandes cuellilargos, como el Braquiosaurio.", "En el Cretácico, el último período, vivieron el Tiranosaurio y el Tricerátops."], ex: { t: "Reloj de la Tierra", m: "un plato de papel, un bolígrafo, una regla", p: ["Dibuja un reloj en el plato, con los números del 1 al 12.", "Marca el comienzo de la Tierra en el 12 de arriba. Pinta un pedacito entre las 11:23 y las 11:49: es la época de los dinosaurios.", "Ahora marca a los humanos: ¡una rayita finita, pegada al 12! ¡Qué nuevos somos en el planeta!"] }, at: "Ficha de las tres épocas", m: "papel, lápices de colores", p: ["Divide una ficha en tres partes: Triásico, Jurásico y Cretácico.", "Dibuja en cada parte un paisaje y un dinosaurio de esa época.", "Pon la ficha en el museo."], q: "Si pudieras visitar uno de los tres períodos, ¿cuál elegirías?" } },

{ e: "⛏️", art: { b: "⛏️", s: ["🦴", "🖌️", "🧒", "🌊"], c: ["#3A3A2A", "#8A8A6A"] },
pt: { h: "O vovô contou a história de uma menina inglesa chamada Mary, que vendia conchas antigas na praia para ajudar a família. “Com uns 12 anos, ela e o irmão acharam o esqueleto de um monstro marinho preso num penhasco”, disse. Nina ficou de boca aberta: “Uma criança cientista!”", t: "Caçadores de fósseis", f: "Os cientistas que estudam fósseis se chamam paleontólogos. Eles procuram em rochas antigas, escavam com pincéis e ferramentas pequenas e anotam tudo com cuidado. Depois, no laboratório, limpam os ossos e montam os esqueletos como quebra-cabeças.", x: "Mary Anning, que nasceu em 1799, encontrou com o irmão o primeiro esqueleto completo de ictiossauro conhecido pelos cientistas, quando ainda era criança. Ela virou uma das maiores caçadoras de fósseis da história!", s: ["Os paleontólogos usam pincéis macios, palitos e até escovas de dente para não quebrar os fósseis.", "Ossos grandes são envolvidos em gesso, como um braço quebrado, para viajar até o museu sem se partir.", "Às vezes leva anos para tirar um esqueleto inteiro da rocha."], ex: { t: "Escavação no gelo", m: "dinossauros de brinquedo pequenos, um pote de plástico, água, congelador, sal, um conta-gotas ou colher, água morna", p: ["Coloque os bonequinhos no pote com água e deixe no congelador de um dia para o outro.", "Desenforme o bloco de gelo numa bandeja: os dinossauros estão “presos na rocha”.", "Use sal e gotas de água morna para libertá-los, devagar, como um paleontólogo. Quem consegue tirar o seu primeiro?"] }, at: "Ficha da Mary Anning", m: "papel, lápis de cor", p: ["Desenhe a Mary Anning na praia com seu martelinho e sua cesta.", "Desenhe o ictiossauro que ela encontrou: um réptil marinho parecido com um golfinho.", "Escreva: “Crianças também podem fazer grandes descobertas!” e coloque no museu."], q: "O que você gostaria de descobrir quando crescer?" },
en: { h: "Grandpa told them about an English girl named Mary, who sold ancient shells on the beach to help her family. “When she was about 12, she and her brother found the skeleton of a sea monster stuck in a cliff,” he said. Nina's mouth fell open: “A kid scientist!”", t: "Fossil hunters", f: "Scientists who study fossils are called paleontologists. They search ancient rocks, dig with brushes and small tools and write everything down carefully. Then, in the lab, they clean the bones and assemble skeletons like puzzles.", x: "Mary Anning, born in 1799, and her brother found the first complete ichthyosaur skeleton known to scientists while she was still a child. She became one of the greatest fossil hunters in history!", s: ["Paleontologists use soft brushes, picks and even toothbrushes so they don't break fossils.", "Big bones are wrapped in plaster, like a broken arm, so they can travel to the museum without cracking.", "Sometimes it takes years to free a whole skeleton from the rock."], ex: { t: "Ice excavation", m: "small toy dinosaurs, a plastic container, water, a freezer, salt, a dropper or spoon, warm water", p: ["Put the toys in the container with water and freeze it overnight.", "Pop the ice block out onto a tray: the dinosaurs are “trapped in rock.”", "Use salt and drops of warm water to free them slowly, like a paleontologist. Who can get theirs out first?"] }, at: "Mary Anning card", m: "paper, colored pencils", p: ["Draw Mary Anning on the beach with her little hammer and basket.", "Draw the ichthyosaur she found: a sea reptile that looked like a dolphin.", "Write: “Kids can make great discoveries too!” and put it in the museum."], q: "What would you like to discover when you grow up?" },
es: { h: "El abuelo contó la historia de una niña inglesa llamada Mary, que vendía conchas antiguas en la playa para ayudar a su familia. “Con unos 12 años, ella y su hermano encontraron el esqueleto de un monstruo marino atrapado en un acantilado”, dijo. Nina se quedó con la boca abierta: “¡Una niña científica!”", t: "Cazadores de fósiles", f: "Los científicos que estudian los fósiles se llaman paleontólogos. Buscan en rocas antiguas, excavan con pinceles y herramientas pequeñas y anotan todo con cuidado. Después, en el laboratorio, limpian los huesos y arman los esqueletos como rompecabezas.", x: "¡Mary Anning, nacida en 1799, encontró con su hermano el primer esqueleto completo de ictiosaurio conocido por los científicos, cuando todavía era niña! Se convirtió en una de las mayores cazadoras de fósiles de la historia.", s: ["Los paleontólogos usan pinceles suaves, palillos y hasta cepillos de dientes para no romper los fósiles.", "Los huesos grandes se envuelven en yeso, como un brazo quebrado, para viajar al museo sin partirse.", "A veces se tarda años en sacar un esqueleto entero de la roca."], ex: { t: "Excavación en el hielo", m: "dinosaurios de juguete pequeños, un recipiente de plástico, agua, congelador, sal, un gotero o cuchara, agua tibia", p: ["Pon los muñequitos en el recipiente con agua y déjalo en el congelador de un día para el otro.", "Desmolda el bloque de hielo en una bandeja: los dinosaurios están “atrapados en la roca”.", "Usa sal y gotas de agua tibia para liberarlos despacio, como un paleontólogo. ¿Quién saca el suyo primero?"] }, at: "Ficha de Mary Anning", m: "papel, lápices de colores", p: ["Dibuja a Mary Anning en la playa con su martillito y su canasta.", "Dibuja el ictiosaurio que encontró: un reptil marino parecido a un delfín.", "Escribe: “¡Los niños también pueden hacer grandes descubrimientos!” y ponla en el museo."], q: "¿Qué te gustaría descubrir cuando seas grande?" } },

{ e: "🥇", art: { b: "🦎", s: ["🦴", "🌿", "🌄", "⭐"], c: ["#0B4F2C", "#4AA05A"] },
pt: { h: "Nina achava que os dinossauros mais importantes eram todos dos Estados Unidos. O vovô abriu o mapa do Brasil e apontou para o Rio Grande do Sul. “Aqui foram encontrados alguns dos dinossauros mais antigos do mundo inteiro!”, disse. Leo pulou do sofá: “Dinossauros brasileiros?”", t: "Os primeiros dinossauros (e eles eram brasileiros!)", f: "Os primeiros dinossauros surgiram no período Triássico, há uns 230 milhões de anos. Eram bem menores que os gigantes famosos: muitos tinham o tamanho de um cachorro grande. Perto de Santa Maria, no Rio Grande do Sul, rochas desse tempo guardam fósseis de alguns dos dinossauros mais antigos já encontrados.", x: "O Buriolestes, um dinossauro de uns 233 milhões de anos achado no Rio Grande do Sul, tinha mais ou menos o tamanho de um cachorro e é um dos dinossauros mais antigos do planeta!", s: ["Outros dinossauros antiquíssimos do Rio Grande do Sul são o Staurikosaurus e o Saturnalia.", "Naquela época, todos os continentes estavam juntos na Pangeia, e o Brasil ficava colado na África.", "Os primeiros dinossauros andavam sobre duas pernas e eram rápidos e leves."], ex: { t: "Do tamanho do dinossauro", m: "um barbante, uma fita métrica, fita adesiva", p: ["Meça 1,5 metro de barbante: é mais ou menos o comprimento de um dos primeiros dinossauros, do focinho à ponta da cauda.", "Estique o barbante no chão e deite ao lado dele. Você é maior ou menor?", "Agora meça o comprimento do seu cachorro, do seu gato ou de um brinquedo grande e compare."] }, at: "Ficha dos dinos gaúchos", m: "papel, lápis de cor", p: ["Desenhe um dinossauro pequeno e rápido correndo numa paisagem do Triássico, com samambaias e rios.", "Escreva o nome “Buriolestes” e a palavra Brasil bem grande.", "Coloque a ficha no museu, num lugar de destaque."], q: "Por que você acha que é importante estudar fósseis no Brasil?" },
en: { h: "Nina thought the most important dinosaurs were all from the United States. Grandpa opened a map of Brazil and pointed to Rio Grande do Sul. “Some of the oldest dinosaurs in the whole world were found here!” he said. Leo jumped off the couch: “Brazilian dinosaurs?”", t: "The first dinosaurs (and they were Brazilian!)", f: "The first dinosaurs appeared in the Triassic period, about 230 million years ago. They were much smaller than the famous giants: many were the size of a big dog. Near Santa Maria, in southern Brazil, rocks from that time hold fossils of some of the oldest dinosaurs ever found.", x: "Buriolestes, a dinosaur about 233 million years old found in southern Brazil, was roughly the size of a dog and is one of the oldest dinosaurs on the planet!", s: ["Other very ancient dinosaurs from southern Brazil include Staurikosaurus and Saturnalia.", "Back then, all the continents were joined in Pangaea, and Brazil was attached to Africa.", "The first dinosaurs walked on two legs and were fast and light."], ex: { t: "Dinosaur-sized", m: "string, a tape measure, tape", p: ["Measure 1.5 meters (5 feet) of string: that's about the length of one of the first dinosaurs, from snout to tail tip.", "Stretch the string on the floor and lie down next to it. Are you bigger or smaller?", "Now measure your dog, your cat or a big toy and compare."] }, at: "Brazilian dino card", m: "paper, colored pencils", p: ["Draw a small, fast dinosaur running through a Triassic landscape, with ferns and rivers.", "Write the name “Buriolestes” and the word Brazil in big letters.", "Put the card in the museum in a place of honor."], q: "Why do you think it's important to study fossils from all over the world?" },
es: { h: "Nina creía que los dinosaurios más importantes eran todos de Estados Unidos. El abuelo abrió el mapa de Brasil y señaló Rio Grande do Sul. “¡Aquí se encontraron algunos de los dinosaurios más antiguos del mundo entero!”, dijo. Leo saltó del sillón: “¿Dinosaurios brasileños?”", t: "Los primeros dinosaurios (¡y eran sudamericanos!)", f: "Los primeros dinosaurios aparecieron en el período Triásico, hace unos 230 millones de años. Eran mucho más pequeños que los gigantes famosos: muchos tenían el tamaño de un perro grande. Cerca de Santa Maria, en el sur de Brasil, y también en Argentina, rocas de esa época guardan fósiles de algunos de los dinosaurios más antiguos encontrados.", x: "¡El Buriolestes, un dinosaurio de unos 233 millones de años hallado en el sur de Brasil, tenía más o menos el tamaño de un perro y es uno de los dinosaurios más antiguos del planeta!", s: ["Otros dinosaurios antiquísimos de Sudamérica son el Staurikosaurus, de Brasil, y el Eoraptor, de Argentina.", "En esa época, todos los continentes estaban juntos en Pangea, y Sudamérica estaba pegada a África.", "Los primeros dinosaurios caminaban sobre dos patas y eran rápidos y livianos."], ex: { t: "Del tamaño del dinosaurio", m: "un cordel, una cinta métrica, cinta adhesiva", p: ["Mide 1,5 metros de cordel: es más o menos el largo de uno de los primeros dinosaurios, del hocico a la punta de la cola.", "Estira el cordel en el piso y acuéstate al lado. ¿Eres más grande o más chico?", "Ahora mide a tu perro, a tu gato o un juguete grande y compara."] }, at: "Ficha de los dinos sudamericanos", m: "papel, lápices de colores", p: ["Dibuja un dinosaurio pequeño y rápido corriendo en un paisaje del Triásico, con helechos y ríos.", "Escribe el nombre “Buriolestes” y la palabra Sudamérica bien grande.", "Pon la ficha en el museo, en un lugar destacado."], q: "¿Por qué crees que es importante estudiar fósiles de todo el mundo?" } },

{ e: "🦕", art: { b: "🦕", s: ["🌲", "🌿", "📏", "🐘"], c: ["#2A4E3A", "#5A9A7A"] },
pt: { h: "Leo tentou pegar um biscoito no alto da prateleira e não alcançou. “Se eu tivesse o pescoço de um dinossauro…”, suspirou. O vovô riu: “Alguns dinossauros tinham pescoços tão compridos que comiam no topo das árvores. Mas isso tinha um preço: o coração precisava ser muito forte!”", t: "Os gigantes pescoçudos", f: "Os saurópodes eram dinossauros enormes, com pescoço e cauda compridíssimos, cabeça pequena e quatro patas como colunas. Comiam plantas o dia inteiro. Eles foram os maiores animais que já andaram sobre a terra.", x: "O Argentinossauro, encontrado na Argentina, pode ter chegado a uns 35 metros de comprimento e pesado tanto quanto uns 10 elefantes! No Brasil viveu o Austroposeidon, com cerca de 25 metros.", s: ["Os saurópodes não mastigavam: engoliam as folhas inteiras e deixavam o estômago fazer o trabalho.", "Os ossos deles tinham espaços cheios de ar, o que deixava o esqueleto mais leve.", "Os filhotes saíam de ovos do tamanho de um melão, pequenos perto do tamanho dos adultos."], ex: { t: "Pescoço comprido no canudo", m: "vários canudos, fita adesiva, um copo com água", p: ["Beba um pouco de água com um canudo só.", "Agora emende 3 ou 4 canudos com fita, bem vedados, e tente beber de novo.", "Fica muito mais difícil puxar a água! Os saurópodes precisavam de um coração fortíssimo para levar sangue até a cabeça lá no alto."] }, at: "Ficha do gigante", m: "papel comprido ou várias folhas emendadas, lápis de cor, fita métrica", p: ["Desenhe um saurópode bem comprido, com o pescoço esticado até o topo de uma árvore.", "Desenhe uma pessoa pequenininha ao lado para mostrar o tamanho.", "Coloque a ficha no museu, que agora vai precisar de uma parede bem grande!"], q: "O que você faria se tivesse um pescoço de 10 metros?" },
en: { h: "Leo tried to grab a cookie from the top shelf and couldn't reach it. “If only I had a dinosaur's neck…” he sighed. Grandpa laughed: “Some dinosaurs had necks so long they ate from the treetops. But there was a price: the heart had to be really strong!”", t: "The long-necked giants", f: "Sauropods were enormous dinosaurs with super-long necks and tails, small heads and four pillar-like legs. They ate plants all day long. They were the biggest animals that ever walked on land.", x: "Argentinosaurus, found in Argentina, may have reached about 35 meters (115 feet) long and weighed as much as about 10 elephants! In Brazil lived Austroposeidon, about 25 meters long.", s: ["Sauropods didn't chew: they swallowed leaves whole and let their stomachs do the work.", "Their bones had air-filled spaces, which made the skeleton lighter.", "Babies hatched from eggs about the size of a melon, tiny compared with the adults."], ex: { t: "Long neck straw", m: "several straws, tape, a glass of water", p: ["Drink some water through a single straw.", "Now tape 3 or 4 straws together end to end, well sealed, and try again.", "It's much harder to pull the water up! Sauropods needed a super-strong heart to pump blood all the way up to their heads."] }, at: "Giant card", m: "long paper or several sheets taped together, colored pencils, a tape measure", p: ["Draw a very long sauropod with its neck stretched up to the top of a tree.", "Draw a tiny person next to it to show the size.", "Put the card in the museum, which now needs a really big wall!"], q: "What would you do if you had a 10-meter neck?" },
es: { h: "Leo intentó agarrar una galletita del estante más alto y no llegó. “Si tuviera el cuello de un dinosaurio…”, suspiró. El abuelo se rió: “Algunos dinosaurios tenían cuellos tan largos que comían en la copa de los árboles. Pero eso tenía un precio: ¡el corazón tenía que ser muy fuerte!”", t: "Los gigantes cuellilargos", f: "Los saurópodos eran dinosaurios enormes, con cuello y cola larguísimos, cabeza pequeña y cuatro patas como columnas. Comían plantas todo el día. Fueron los animales más grandes que caminaron sobre la tierra.", x: "¡El Argentinosaurio, hallado en Argentina, pudo haber llegado a unos 35 metros de largo y pesado tanto como unos 10 elefantes! En Brasil vivió el Austroposeidon, de unos 25 metros.", s: ["Los saurópodos no masticaban: tragaban las hojas enteras y dejaban que el estómago hiciera el trabajo.", "Sus huesos tenían espacios llenos de aire, lo que hacía más liviano el esqueleto.", "Las crías salían de huevos del tamaño de un melón, pequeñísimas al lado de los adultos."], ex: { t: "Cuello largo en la pajita", m: "varias pajitas, cinta adhesiva, un vaso con agua", p: ["Toma un poco de agua con una sola pajita.", "Ahora une 3 o 4 pajitas con cinta, bien selladas, e intenta otra vez.", "¡Cuesta mucho más subir el agua! Los saurópodos necesitaban un corazón fortísimo para llevar sangre hasta la cabeza allá arriba."] }, at: "Ficha del gigante", m: "papel largo o varias hojas unidas, lápices de colores, cinta métrica", p: ["Dibuja un saurópodo bien largo, con el cuello estirado hasta la copa de un árbol.", "Dibuja una persona chiquitita al lado para mostrar el tamaño.", "Pon la ficha en el museo, ¡que ahora va a necesitar una pared bien grande!"], q: "¿Qué harías si tuvieras un cuello de 10 metros?" } },

{ e: "👑", art: { b: "🦖", s: ["🦷", "💪", "👑", "🌋"], c: ["#5A1B0B", "#C24A2C"] },
pt: { h: "Leo encolheu os braços junto ao peito, como um tiranossauro, e tentou pegar o controle remoto. Não conseguiu! Nina riu tanto que caiu do sofá. “Os bracinhos eram curtos”, disse o vovô, “mas não se engane: o T. rex tinha a mordida mais forte de qualquer animal terrestre que já existiu!”", t: "O Tiranossauro rex", f: "O Tiranossauro rex, que quer dizer “rei dos lagartos tiranos”, viveu na América do Norte no fim do Cretáceo, entre uns 68 e 66 milhões de anos atrás. Tinha até 12 metros de comprimento, uma cabeça enorme e dentes do tamanho de bananas.", x: "Os cientistas calculam que a mordida do T. rex era forte o bastante para esmagar ossos. Ele tinha a mordida mais poderosa já estimada para um animal que viveu em terra firme!", s: ["Os braços do T. rex tinham só uns 1 metro, mas eram musculosos.", "Ele tinha um ótimo olfato e enxergava bem, com os olhos virados para a frente.", "O esqueleto de T. rex mais famoso se chama Sue e está num museu em Chicago."], ex: { t: "Desafio dos braços de T. rex", m: "objetos da casa (escova de dentes, meia, copo de plástico), um relógio", p: ["Encoste os cotovelos nas costelas e use só as mãos e os antebraços, como um T. rex.", "Tente fazer tarefas: calçar uma meia, pegar um copo, escovar os dentes. Cronometre!", "Agora faça com os braços normais e compare. Que dinossauro difícil de ser!"] }, at: "Ficha do rei", m: "papel, lápis de cor, régua", p: ["Desenhe o T. rex e escreva o tamanho dele: 12 metros de comprimento, uns 4 metros de altura.", "Desenhe um dente do tamanho real, uns 30 centímetros, com a raiz.", "Coloque a ficha no museu com uma coroa desenhada."], q: "Você acha que o T. rex era mais caçador ou mais comedor de restos? Por quê?" },
en: { h: "Leo tucked his arms against his chest like a T. rex and tried to grab the remote. He couldn't! Nina laughed so hard she fell off the couch. “The little arms were short,” Grandpa said, “but don't be fooled: T. rex had the strongest bite of any land animal that ever lived!”", t: "Tyrannosaurus rex", f: "Tyrannosaurus rex, which means “tyrant lizard king,” lived in North America at the end of the Cretaceous, about 68 to 66 million years ago. It was up to 12 meters (40 feet) long, with a huge head and teeth the size of bananas.", x: "Scientists estimate that T. rex's bite was strong enough to crush bone. It had the most powerful bite ever estimated for an animal that lived on land!", s: ["T. rex's arms were only about 1 meter (3 feet) long, but they were muscular.", "It had an excellent sense of smell and good eyesight, with forward-facing eyes.", "The most famous T. rex skeleton is called Sue, and it's in a museum in Chicago."], ex: { t: "T. rex arms challenge", m: "household objects (toothbrush, sock, plastic cup), a clock", p: ["Press your elbows to your ribs and use only your hands and forearms, like a T. rex.", "Try some tasks: putting on a sock, picking up a cup, brushing your teeth. Time yourself!", "Now do them with your arms normal and compare. What a tough dinosaur to be!"] }, at: "King card", m: "paper, colored pencils, ruler", p: ["Draw the T. rex and write its size: 12 meters long, about 4 meters tall.", "Draw one tooth at real size, about 30 cm (12 inches) including the root.", "Put the card in the museum with a crown drawn on it."], q: "Do you think T. rex was more of a hunter or a scavenger? Why?" },
es: { h: "Leo pegó los brazos al pecho, como un tiranosaurio, e intentó agarrar el control remoto. ¡No pudo! Nina se rió tanto que se cayó del sillón. “Los bracitos eran cortos”, dijo el abuelo, “pero no te confundas: ¡el T. rex tenía la mordida más fuerte de todos los animales terrestres que existieron!”", t: "El Tiranosaurio rex", f: "El Tiranosaurio rex, que quiere decir “rey de los lagartos tiranos”, vivió en América del Norte a fines del Cretácico, hace entre unos 68 y 66 millones de años. Medía hasta 12 metros de largo, tenía una cabeza enorme y dientes del tamaño de bananas.", x: "¡Los científicos calculan que la mordida del T. rex era tan fuerte que podía triturar huesos! Tenía la mordida más poderosa estimada para un animal que vivió en tierra firme.", s: ["Los brazos del T. rex medían solo 1 metro, pero eran musculosos.", "Tenía un olfato excelente y buena vista, con los ojos mirando hacia adelante.", "El esqueleto de T. rex más famoso se llama Sue y está en un museo de Chicago."], ex: { t: "Desafío de los brazos de T. rex", m: "objetos de la casa (cepillo de dientes, media, vaso de plástico), un reloj", p: ["Pega los codos a las costillas y usa solo las manos y los antebrazos, como un T. rex.", "Intenta hacer tareas: ponerte una media, agarrar un vaso, cepillarte los dientes. ¡Cronométralo!", "Ahora hazlo con los brazos normales y compara. ¡Qué difícil es ser este dinosaurio!"] }, at: "Ficha del rey", m: "papel, lápices de colores, regla", p: ["Dibuja el T. rex y escribe su tamaño: 12 metros de largo, unos 4 metros de alto.", "Dibuja un diente de tamaño real, unos 30 centímetros, con la raíz.", "Pon la ficha en el museo con una corona dibujada."], q: "¿Crees que el T. rex era más cazador o más carroñero? ¿Por qué?" } },

{ e: "🛡️", art: { b: "🦏", s: ["🌿", "🛡️", "🦷", "🦖"], c: ["#4E3A0B", "#B08A2C"] },
pt: { h: "Nina montou um dinossauro de massinha com três chifres e uma gola enorme atrás da cabeça. “Para que serve essa gola?”, perguntou Leo. “Os cientistas ainda discutem”, respondeu o vovô. “Talvez para se proteger, talvez para se exibir, como a cauda do pavão!”", t: "Tricerátops e os dinossauros de chifres", f: "O Tricerátops era um dinossauro comedor de plantas com três chifres no rosto e uma gola grande de osso atrás da cabeça. Tinha uns 9 metros de comprimento e viveu no fim do Cretáceo, na mesma época e no mesmo lugar que o Tiranossauro rex.", x: "O Tricerátops tinha centenas de dentes organizados em fileiras, que iam sendo trocados a vida toda! Eles funcionavam como tesouras para cortar plantas duras.", s: ["O nome Tricerátops quer dizer “cara com três chifres”.", "Já foram encontrados fósseis de Tricerátops com marcas de mordida de T. rex.", "Ele tinha um bico parecido com o de um papagaio na frente da boca."], ex: { t: "Dentes de tesoura", m: "folhas de couve ou alface, uma tesoura sem ponta, as mãos", p: ["Tente rasgar uma folha dura só puxando com os dedos.", "Agora corte a mesma folha com a tesoura.", "A tesoura corta muito mais fácil e retinho! Os dentes do Tricerátops se encaixavam como lâminas de tesoura."] }, at: "Ficha do Tricerátops", m: "papel, lápis de cor", p: ["Desenhe um Tricerátops com a gola colorida, como se ele estivesse se exibindo.", "Invente um padrão de cores para a gola: listras, bolinhas ou manchas.", "Coloque a ficha no museu, ao lado do T. rex, porque eram vizinhos!"], q: "Se você tivesse uma gola enorme, de que cor ela seria?" },
en: { h: "Nina built a play dough dinosaur with three horns and a huge frill behind its head. “What's that frill for?” Leo asked. “Scientists are still debating,” Grandpa answered. “Maybe for protection, maybe for showing off, like a peacock's tail!”", t: "Triceratops and the horned dinosaurs", f: "Triceratops was a plant-eating dinosaur with three horns on its face and a big bony frill behind its head. It was about 9 meters (30 feet) long and lived at the end of the Cretaceous, at the same time and place as Tyrannosaurus rex.", x: "Triceratops had hundreds of teeth arranged in rows, replaced throughout its life! They worked like scissors to slice tough plants.", s: ["The name Triceratops means “three-horned face.”", "Triceratops fossils have been found with T. rex bite marks.", "It had a beak like a parrot's at the front of its mouth."], ex: { t: "Scissor teeth", m: "kale or lettuce leaves, safety scissors, your hands", p: ["Try tearing a tough leaf just by pulling with your fingers.", "Now cut the same leaf with the scissors.", "The scissors cut much more easily and neatly! Triceratops teeth fit together like scissor blades."] }, at: "Triceratops card", m: "paper, colored pencils", p: ["Draw a Triceratops with a colorful frill, as if it were showing off.", "Invent a color pattern for the frill: stripes, dots or spots.", "Put the card in the museum next to the T. rex, because they were neighbors!"], q: "If you had a giant frill, what color would it be?" },
es: { h: "Nina armó un dinosaurio de plastilina con tres cuernos y un collar enorme detrás de la cabeza. “¿Para qué sirve ese collar?”, preguntó Leo. “Los científicos todavía lo discuten”, respondió el abuelo. “¡Tal vez para protegerse, tal vez para lucirse, como la cola del pavo real!”", t: "El Tricerátops y los dinosaurios con cuernos", f: "El Tricerátops era un dinosaurio herbívoro con tres cuernos en la cara y un gran collar de hueso detrás de la cabeza. Medía unos 9 metros de largo y vivió a fines del Cretácico, en la misma época y lugar que el Tiranosaurio rex.", x: "¡El Tricerátops tenía cientos de dientes ordenados en filas, que se iban cambiando toda la vida! Funcionaban como tijeras para cortar plantas duras.", s: ["El nombre Tricerátops quiere decir “cara con tres cuernos”.", "Se encontraron fósiles de Tricerátops con marcas de mordidas de T. rex.", "Tenía un pico parecido al de un loro en la parte de adelante de la boca."], ex: { t: "Dientes de tijera", m: "hojas de repollo o lechuga, una tijera sin punta, las manos", p: ["Intenta romper una hoja dura solo tirando con los dedos.", "Ahora corta la misma hoja con la tijera.", "¡La tijera corta mucho más fácil y derecho! Los dientes del Tricerátops encajaban como las hojas de una tijera."] }, at: "Ficha del Tricerátops", m: "papel, lápices de colores", p: ["Dibuja un Tricerátops con el collar de colores, como si se estuviera luciendo.", "Inventa un diseño de colores para el collar: rayas, lunares o manchas.", "Pon la ficha en el museo, al lado del T. rex, ¡porque eran vecinos!"], q: "Si tuvieras un collar enorme, ¿de qué color sería?" } },

{ e: "🦔", art: { b: "🦔", s: ["🛡️", "🔨", "🦖", "⏳"], c: ["#3A3A1B", "#8A8A3A"] },
pt: { h: "Leo achava que o Estegossauro e o T. rex brigavam nos filmes. O vovô fez uma conta no papel e mostrou: “Na verdade, o T. rex viveu mais perto de nós no tempo do que do Estegossauro!” Nina e Leo se olharam, confusos. Os números não mentiam.", t: "Os dinossauros de armadura", f: "Alguns dinossauros comedores de plantas tinham armaduras incríveis. O Estegossauro tinha placas grandes nas costas e espinhos na cauda. O Anquilossauro era coberto de placas de osso, como um tanque, e tinha uma clava pesada na ponta da cauda.", x: "O Estegossauro viveu há uns 150 milhões de anos, e o T. rex, há uns 67 milhões. Entre os dois, passaram mais de 80 milhões de anos, mais do que entre o T. rex e nós!", s: ["O cérebro do Estegossauro era pequeno, mais ou menos do tamanho de um limão, num corpo do tamanho de um ônibus.", "A clava da cauda do Anquilossauro podia acertar a perna de um predador com muita força.", "As placas do Estegossauro talvez ajudassem a esquentar ou esfriar o corpo e a impressionar outros da espécie."], ex: { t: "Qual armadura protege mais?", m: "três biscoitos de água e sal, uma folha de papel, uma esponja de cozinha, uma bolinha de gude", p: ["Coloque um biscoito sem nada, outro coberto pela folha de papel e outro coberto pela esponja.", "Solte a bolinha de gude da mesma altura em cima de cada um.", "Qual biscoito sobreviveu? Armaduras grossas e que amortecem protegem melhor, como a do Anquilossauro!"] }, at: "Ficha dos blindados", m: "papel, lápis de cor", p: ["Desenhe um Estegossauro com as placas e um Anquilossauro com a clava.", "Desenhe uma linha do tempo mostrando o Estegossauro, o T. rex e você, com as distâncias certas.", "Coloque a ficha no museu."], q: "Se você fosse um dinossauro, preferiria ter armadura, velocidade ou tamanho?" },
en: { h: "Leo thought Stegosaurus and T. rex fought each other, like in the movies. Grandpa did some math on paper and showed him: “Actually, T. rex lived closer in time to us than to Stegosaurus!” Nina and Leo looked at each other, confused. The numbers didn't lie.", t: "The armored dinosaurs", f: "Some plant-eating dinosaurs had amazing armor. Stegosaurus had big plates on its back and spikes on its tail. Ankylosaurus was covered in bony plates like a tank and had a heavy club at the end of its tail.", x: "Stegosaurus lived about 150 million years ago, and T. rex about 67 million. More than 80 million years passed between them, more than between T. rex and us!", s: ["Stegosaurus had a small brain, about the size of a lime, in a body the size of a bus.", "Ankylosaurus's tail club could hit a predator's leg with great force.", "Stegosaurus's plates may have helped warm or cool its body and impress others of its kind."], ex: { t: "Which armor protects best?", m: "three crackers, a sheet of paper, a kitchen sponge, a marble", p: ["Leave one cracker bare, cover another with the paper and cover the third with the sponge.", "Drop the marble from the same height onto each one.", "Which cracker survived? Thick, cushioning armor protects best, like Ankylosaurus's!"] }, at: "Armored card", m: "paper, colored pencils", p: ["Draw a Stegosaurus with its plates and an Ankylosaurus with its club.", "Draw a timeline showing Stegosaurus, T. rex and you, with the right distances.", "Put the card in the museum."], q: "If you were a dinosaur, would you rather have armor, speed or size?" },
es: { h: "Leo creía que el Estegosaurio y el T. rex peleaban, como en las películas. El abuelo hizo una cuenta en un papel y le mostró: “¡En realidad, el T. rex vivió más cerca de nosotros en el tiempo que del Estegosaurio!” Nina y Leo se miraron, confundidos. Los números no mentían.", t: "Los dinosaurios con armadura", f: "Algunos dinosaurios herbívoros tenían armaduras increíbles. El Estegosaurio tenía placas grandes en la espalda y púas en la cola. El Anquilosaurio estaba cubierto de placas de hueso, como un tanque, y tenía una maza pesada en la punta de la cola.", x: "¡El Estegosaurio vivió hace unos 150 millones de años, y el T. rex hace unos 67 millones! Entre los dos pasaron más de 80 millones de años, más que entre el T. rex y nosotros.", s: ["El cerebro del Estegosaurio era pequeño, más o menos del tamaño de un limón, en un cuerpo del tamaño de un autobús.", "La maza de la cola del Anquilosaurio podía golpear la pata de un depredador con mucha fuerza.", "Las placas del Estegosaurio quizás lo ayudaban a calentar o enfriar el cuerpo y a impresionar a otros de su especie."], ex: { t: "¿Qué armadura protege más?", m: "tres galletitas de agua, una hoja de papel, una esponja de cocina, una canica", p: ["Deja una galletita sin nada, cubre otra con la hoja de papel y otra con la esponja.", "Suelta la canica desde la misma altura sobre cada una.", "¿Qué galletita sobrevivió? Las armaduras gruesas y que amortiguan protegen mejor, ¡como la del Anquilosaurio!"] }, at: "Ficha de los blindados", m: "papel, lápices de colores", p: ["Dibuja un Estegosaurio con sus placas y un Anquilosaurio con su maza.", "Dibuja una línea de tiempo mostrando el Estegosaurio, el T. rex y a ti, con las distancias correctas.", "Pon la ficha en el museo."], q: "Si fueras un dinosaurio, ¿preferirías tener armadura, velocidad o tamaño?" } },

{ e: "🦃", art: { b: "🦃", s: ["🪶", "🦶", "🏃", "🔍"], c: ["#4E2A1B", "#B05A3A"] },
pt: { h: "Leo tinha visto num filme Velocirraptores enormes e assustadores, sem penas. O vovô mostrou uma ilustração feita por cientistas: um bicho do tamanho de um peru, coberto de penas. “Esse é o Velocirraptor de verdade”, disse. Leo achou fofo. “Fofo, mas esperto e rápido!”, avisou o vovô.", t: "Os raptores", f: "Os raptores eram dinossauros carnívoros ágeis, com uma garra grande e curva em cada pé. O Velocirraptor, que viveu na Mongólia, tinha mais ou menos o tamanho de um peru grande e era coberto de penas. Ele não conseguia voar, mas corria rápido e caçava animais pequenos.", x: "Em 2007, cientistas encontraram no braço de um Velocirraptor marquinhas onde as penas se prendiam, igualzinho às que existem nos ossos das aves de hoje!", s: ["O Velocirraptor dos filmes é bem maior que o real e foi inspirado em parentes maiores, como o Deinonico.", "A garra do pé ficava levantada enquanto ele andava, para não gastar a ponta.", "Os raptores tinham cérebros relativamente grandes para dinossauros."], ex: { t: "Garras de pregador", m: "pregadores de roupa, bolinhas de papel, pompons ou feijões, dois potinhos", p: ["Prenda um pregador entre os dedos e use como uma garra.", "Tente transferir 10 bolinhas de um potinho para o outro usando só a garra.", "Cronometre e depois tente com a mão normal. Que ferramenta incrível era a garra dos raptores!"] }, at: "Ficha do raptor de verdade", m: "papel, lápis de cor, penas ou papel picado (opcional)", p: ["Desenhe um Velocirraptor do tamanho certo, ao lado de um peru para comparar.", "Cubra o desenho de penas coloridas, de verdade ou desenhadas.", "Escreva “Filme x Realidade” e coloque a ficha no museu."], q: "Por que você acha que os filmes mudam como os dinossauros eram?" },
en: { h: "Leo had seen huge, scary, featherless Velociraptors in a movie. Grandpa showed him an illustration made by scientists: an animal the size of a turkey, covered in feathers. “That's the real Velociraptor,” he said. Leo thought it was cute. “Cute, but clever and fast!” Grandpa warned.", t: "Raptors", f: "Raptors were nimble meat-eating dinosaurs with a big curved claw on each foot. Velociraptor, which lived in Mongolia, was about the size of a large turkey and covered in feathers. It couldn't fly, but it ran fast and hunted small animals.", x: "In 2007, scientists found little bumps on a Velociraptor's arm bone where feathers attached, just like the ones on the bones of today's birds!", s: ["Movie Velociraptors are much bigger than the real thing and were inspired by larger relatives like Deinonychus.", "The foot claw was held up off the ground while it walked, so the tip wouldn't wear down.", "Raptors had fairly large brains for dinosaurs."], ex: { t: "Clothespin claws", m: "clothespins, paper balls, pompoms or beans, two small bowls", p: ["Hold a clothespin between your fingers and use it like a claw.", "Try to move 10 balls from one bowl to the other using only your claw.", "Time it, then try with your regular hand. What an amazing tool the raptors' claw was!"] }, at: "Real raptor card", m: "paper, colored pencils, feathers or paper scraps (optional)", p: ["Draw a correctly sized Velociraptor next to a turkey for comparison.", "Cover the drawing with colorful feathers, real or drawn.", "Write “Movie vs. Reality” and put the card in the museum."], q: "Why do you think movies change how dinosaurs really looked?" },
es: { h: "Leo había visto en una película Velocirraptores enormes y aterradores, sin plumas. El abuelo le mostró una ilustración hecha por científicos: un bicho del tamaño de un pavo, cubierto de plumas. “Este es el Velocirraptor de verdad”, dijo. A Leo le pareció tierno. “¡Tierno, pero listo y rápido!”, avisó el abuelo.", t: "Los raptores", f: "Los raptores eran dinosaurios carnívoros ágiles, con una garra grande y curva en cada pie. El Velocirraptor, que vivió en Mongolia, tenía más o menos el tamaño de un pavo grande y estaba cubierto de plumas. No podía volar, pero corría rápido y cazaba animales pequeños.", x: "¡En 2007, científicos encontraron en el brazo de un Velocirraptor marquitas donde se sujetaban las plumas, igualitas a las de los huesos de las aves de hoy!", s: ["El Velocirraptor de las películas es mucho más grande que el real y se inspiró en parientes más grandes, como el Deinonychus.", "La garra del pie quedaba levantada mientras caminaba, para no gastar la punta.", "Los raptores tenían cerebros relativamente grandes para ser dinosaurios."], ex: { t: "Garras de broche", m: "broches de ropa, bolitas de papel, pompones o frijoles, dos potecitos", p: ["Sostén un broche entre los dedos y úsalo como una garra.", "Intenta pasar 10 bolitas de un potecito al otro usando solo la garra.", "Cronométralo y después prueba con la mano normal. ¡Qué herramienta increíble era la garra de los raptores!"] }, at: "Ficha del raptor de verdad", m: "papel, lápices de colores, plumas o papel picado (opcional)", p: ["Dibuja un Velocirraptor del tamaño correcto, al lado de un pavo para comparar.", "Cubre el dibujo de plumas de colores, de verdad o dibujadas.", "Escribe “Película vs. Realidad” y pon la ficha en el museo."], q: "¿Por qué crees que las películas cambian cómo eran los dinosaurios?" } },

{ e: "🐦", art: { b: "🐦", s: ["🪶", "🦖", "🐔", "🕊️"], c: ["#1B3A5A", "#4A8AC2"] },
pt: { h: "No quintal, Nina apontou para um sabiá ciscando a grama e disse, brincando: “Olha um dinossauro!”. O vovô respondeu bem sério: “Você está certíssima.” Leo achou que era piada, mas não era: os pássaros são, de verdade, dinossauros que sobreviveram até hoje.", t: "Os dinossauros ainda estão entre nós", f: "Os cientistas descobriram que as aves descendem de pequenos dinossauros carnívoros com penas. Por isso, as aves são consideradas dinossauros vivos! Muitos dinossauros tinham penas, que no começo serviam para aquecer o corpo e se exibir, e não para voar.", x: "O Archaeopteryx, que viveu há uns 150 milhões de anos, tinha penas e asas como uma ave, mas também dentes, garras nas asas e uma cauda comprida de ossos, como um dinossauro!", s: ["As galinhas, os pombos e os beija-flores são parentes, bem distantes, do T. rex.", "Dinossauros e aves compartilham ossos ocos, uma fúrcula (o “ossinho da sorte”) e até o jeito de botar ovos em ninhos.", "Na China foram encontrados centenas de fósseis de dinossauros com penas muito bem conservadas."], ex: { t: "Penas que aquecem", m: "dois copos iguais com água morna, algodão ou enchimento de travesseiro, um pano ou meia, um relógio", p: ["Encha os dois copos com água morna da torneira, na mesma quantidade.", "Envolva um copo com bastante algodão ou enchimento e prenda com o pano. Deixe o outro descoberto.", "Espere 20 minutos e toque a água dos dois com o dedo. Qual está mais quentinha? As penas dos dinossauros funcionavam como esse casaco!"] }, at: "Ficha do dinossauro do quintal", m: "papel, lápis de cor", p: ["Observe um pássaro de verdade no quintal, na rua ou na janela.", "Desenhe o pássaro e, ao lado, um pequeno dinossauro com penas. Circule o que eles têm em comum.", "Coloque a ficha no museu com o título “Dinossauros vivos”."], q: "Qual pássaro você já viu que parece mais com um dinossauro?" },
en: { h: "In the backyard, Nina pointed at a thrush pecking the grass and joked, “Look, a dinosaur!” Grandpa answered very seriously, “You're absolutely right.” Leo thought it was a joke, but it wasn't: birds really are dinosaurs that survived to this day.", t: "Dinosaurs are still among us", f: "Scientists discovered that birds descend from small feathered meat-eating dinosaurs. That's why birds are considered living dinosaurs! Many dinosaurs had feathers, which at first were for keeping warm and showing off, not for flying.", x: "Archaeopteryx, which lived about 150 million years ago, had feathers and wings like a bird, but also teeth, claws on its wings and a long bony tail, like a dinosaur!", s: ["Chickens, pigeons and hummingbirds are very distant relatives of T. rex.", "Dinosaurs and birds share hollow bones, a wishbone and even the habit of laying eggs in nests.", "In China, hundreds of dinosaur fossils with beautifully preserved feathers have been found."], ex: { t: "Feathers that keep warm", m: "two identical cups of warm water, cotton or pillow stuffing, a cloth or sock, a clock", p: ["Fill both cups with the same amount of warm tap water.", "Wrap one cup in plenty of cotton or stuffing and hold it in place with the cloth. Leave the other uncovered.", "Wait 20 minutes and touch the water in each with your finger. Which is warmer? Dinosaur feathers worked like that coat!"] }, at: "Backyard dinosaur card", m: "paper, colored pencils", p: ["Watch a real bird in the yard, on the street or from the window.", "Draw the bird and, next to it, a small feathered dinosaur. Circle what they have in common.", "Put the card in the museum with the title “Living dinosaurs.”"], q: "Which bird have you seen that looks most like a dinosaur?" },
es: { h: "En el patio, Nina señaló un zorzal picoteando el pasto y dijo, en broma: “¡Mira, un dinosaurio!”. El abuelo respondió muy serio: “Tienes toda la razón.” Leo pensó que era un chiste, pero no lo era: los pájaros son, de verdad, dinosaurios que sobrevivieron hasta hoy.", t: "Los dinosaurios siguen entre nosotros", f: "Los científicos descubrieron que las aves descienden de pequeños dinosaurios carnívoros con plumas. ¡Por eso las aves se consideran dinosaurios vivos! Muchos dinosaurios tenían plumas, que al principio servían para calentar el cuerpo y lucirse, y no para volar.", x: "¡El Archaeopteryx, que vivió hace unos 150 millones de años, tenía plumas y alas como un ave, pero también dientes, garras en las alas y una cola larga de huesos, como un dinosaurio!", s: ["Las gallinas, las palomas y los colibríes son parientes, muy lejanos, del T. rex.", "Los dinosaurios y las aves comparten huesos huecos, una fúrcula (el “hueso de la suerte”) y hasta la costumbre de poner huevos en nidos.", "En China se encontraron cientos de fósiles de dinosaurios con plumas muy bien conservadas."], ex: { t: "Plumas que abrigan", m: "dos vasos iguales con agua tibia, algodón o relleno de almohada, un paño o una media, un reloj", p: ["Llena los dos vasos con agua tibia de la canilla, en la misma cantidad.", "Envuelve un vaso con mucho algodón o relleno y sujétalo con el paño. Deja el otro descubierto.", "Espera 20 minutos y toca el agua de los dos con el dedo. ¿Cuál está más calentita? ¡Las plumas de los dinosaurios funcionaban como ese abrigo!"] }, at: "Ficha del dinosaurio del patio", m: "papel, lápices de colores", p: ["Observa un pájaro de verdad en el patio, en la calle o por la ventana.", "Dibuja el pájaro y, al lado, un pequeño dinosaurio con plumas. Encierra en un círculo lo que tienen en común.", "Pon la ficha en el museo con el título “Dinosaurios vivos”."], q: "¿Qué pájaro viste que se parece más a un dinosaurio?" } },
];
